nt.querySelectorAll('[data-office-name]')).some(office => office.dataset.officeName.toLocaleLowerCase().includes(officeSearch.trim().toLocaleLowerCase()))" role="status" class="text-sm text-gray-500">No matching offices.</p></div><template x-for="officeId in selectedOffices" :key="officeId"><div><input type="hidden" name="office_ids[]" :value="officeId"><input type="hidden" :name="`office_allocations[${officeId}]`" :value="allocations[officeId]"></div></template><x-input-error :messages="$errors->get('office_ids')" class="mt-2"/><x-input-error :messages="$errors->get('office_allocations')" class="mt-2"/></div>
