<script>
function officeTargetAllocator(selectedOffices, allocations, targetValue) {
    return {
        selectedOffices: selectedOffices.map(Number), allocations, targetValue: Number(targetValue),
        askForAllocation(officeId, officeName) {
            const current = this.allocations[officeId] ?? '';
            const answer = window.prompt(`Target allocation for ${officeName}:`, current);
            if (answer === null) return false;
            const value = Number(answer);
            if (!Number.isFinite(value) || value <= 0) { window.alert('Enter a target allocation greater than zero.'); return false; }
            this.allocations[officeId] = value;
            return true;
        },
        toggleOffice(event, officeId, officeName) {
            if (event.target.checked) {
                if (this.askForAllocation(officeId, officeName)) this.selectedOffices.push(officeId);
                else event.target.checked = false;
            } else {
                this.selectedOffices = this.selectedOffices.filter(id => id !== officeId);
                delete this.allocations[officeId];
            }
        },
        editAllocation(officeId, officeName) { this.askForAllocation(officeId, officeName); },
        allocatedTotal() { return this.selectedOffices.reduce((sum, id) => sum + Number(this.allocations[id] || 0), 0); },
        remaining() { return Number(this.targetValue || 0) - this.allocatedTotal(); },
        allocationIsComplete() { return this.selectedOffices.length > 0 && Math.abs(this.remaining()) < 0.005; },
        formatAllocation(officeId) { return Number(this.allocations[officeId] || 0).toFixed(2); }
    };
}
</script>
